{"content":"import json
import os
from typing import List
from src.models import Question

class QuizLoader:
    def _to_question(self, data: dict) -> Question:
        try:
            return Question(
                id=data['id'],
                text=data['text'],
                options=data['options'],
                correct_option_index=data['correct_option_index'],
                category=data.get('category', 'General'),
                difficulty=data.get('difficulty', 'Easy')
            )
        except KeyError as e:
            raise ValueError(f"Missing required field in question data: {e}")

    def load_from_json(self, file_path: str) -> List[Question]:
        if not os.path.exists(file_path):
            raise FileNotFoundError(f"JSON file not found: {file_path}")

        with open(file_path, 'r', encoding='utf-8') as f:
            try:
                data = json.load(f)
            except json.JSONDecodeError as e:
                raise ValueError(f"Invalid JSON format in {file_path}: {str(e)}")

        if not isinstance(data, list):
            raise ValueError(f"JSON content in {file_path} must be a list of questions.")

        questions = []
        for item in data:
            questions.append(self._to_question(item))
        return questions

    def load_all_from_dir(self, directory: str) -> List[Question]:
        all_questions = []
        if not os.pathisdir(directory):
            raise NotADirectoryError(f"Not a directory: {directory}")

        for filename in os.listdir(directory):
            if filename.endswith('.json'):
                file_path = os.path.join(directory, filename)
                all_questions.extend(self.load_from_json(file_path))

        return all_questions
